<script setup lang="ts">import{useId}from'vue';interface Props{text:string;placement?:'top'|'bottom'|'left'|'right'};withDefaults(defineProps<Props>(),{placement:'top'});const id=`uv-tooltip-${useId()}`</script>
<template><span class="uv-tooltip"><span class="uv-tooltip__trigger" :aria-describedby="id"><slot/></span><span :id="id" class="uv-tooltip__bubble" :class="`uv-tooltip__bubble--${placement}`" role="tooltip">{{text}}</span></span></template>
<style>.uv-tooltip{position:relative;display:inline-flex}.uv-tooltip__trigger{display:inline-flex}.uv-tooltip__bubble{position:absolute;z-index:20;width:max-content;max-width:220px;padding:.4rem .55rem;border-radius:.4rem;background:#0f172a;color:#fff;font-family:var(--uv-font-sans,system-ui,sans-serif);font-size:.75rem;line-height:1.3;opacity:0;pointer-events:none;transform:translate(-50%,-4px);transition:opacity .12s,transform .12s}.uv-tooltip:hover .uv-tooltip__bubble,.uv-tooltip:focus-within .uv-tooltip__bubble{opacity:1}.uv-tooltip__bubble--top{left:50%;bottom:calc(100% + .45rem)}.uv-tooltip__bubble--bottom{left:50%;top:calc(100% + .45rem);transform:translate(-50%,4px)}.uv-tooltip__bubble--left{right:calc(100% + .45rem);top:50%;transform:translate(-4px,-50%)}.uv-tooltip__bubble--right{left:calc(100% + .45rem);top:50%;transform:translate(4px,-50%)}</style>
